// seed: tests/seed.parent.spec.ts
// Только просмотр (без @data): форма запроса проверки открывается, но НЕ отправляется. Проект iphone (WebKit 375).
// Данные: у QA-R2-1 в «תצפיות» есть попытка чтения с кнопкой «לא מסכימים? בקשת בדיקה».
// Не прогонять при записи — запуск только по /qa-regress.
import * as path from 'path';
import { test, expect } from '../../fixtures';
import { expectInsideViewport, expectNoHorizontalScroll } from '../placement-reading/reading.helpers';

test.use({ storageState: path.resolve(__dirname, '../../../auth/parent.json') });

const CHILD_ID = 'b9ef1552-4cc7-4d72-a9c3-d02d66d19af1'; // QA-R2-1, постоянный

test.describe('Отзыв о чтении — запрос проверки на телефоне (autotest-writer)', () => {
  test('Телефон: на /appeal «ביטול» и «חזרה» внутри карточки, без горизонтальной прокрутки; «ביטול» ведёт на наблюдения @iphone @prod-safe #eee921', async ({ page }) => {
    await page.goto(`/children/${CHILD_ID}/observations`);
    const disagree = page.getByRole('button', { name: /לא מסכימים/ }).or(page.getByRole('link', { name: /לא מסכימים/ })).filter({ visible: true });
    // TODO verify selector: если кнопка только в карточке попытки — открыть первую попытку чтения
    if ((await disagree.count()) === 0) {
      await page.getByRole('button').filter({ hasText: /ודאות|קריאה/ }).filter({ visible: true }).first().click();
    }
    await disagree.first().click();
    await page.waitForURL(/\/appeal(\?|$)/);

    // F2 (коммент. 29.10 п.2): на 390 «ביטול» отдельной строкой в карточке; без горизонтальной прокрутки
    await expectNoHorizontalScroll(page, '/appeal');
    const cancel = page.getByRole('button', { name: 'ביטול', exact: true }).filter({ visible: true }).first();
    const back = page.getByRole('button', { name: 'חזרה', exact: true }).or(page.getByRole('link', { name: 'חזרה', exact: true })).filter({ visible: true }).first();
    await expectInsideViewport(page, cancel, '«ביטול»');
    await expectInsideViewport(page, back, '«חזרה»');

    // Выбор причины: aria-checked (реджект 01.11 п.2)
    const reason = page.getByRole('radio').filter({ visible: true }).first(); // TODO verify selector (причины — role=radio)
    await reason.click();
    await expect(reason).toHaveAttribute('aria-checked', 'true');

    // «ביטול» после reload (прямая ссылка) — назад на наблюдения, без отправки (реджект 01.11 п.1)
    await page.reload();
    await page.getByRole('button', { name: 'ביטול', exact: true }).filter({ visible: true }).first().click();
    await page.waitForURL(new RegExp(`/children/${CHILD_ID}/observations`));
  });
});
